CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_version VALUES(1,strftime('%Y-%m-%dT%H:%M:%SZ','now'));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('admin','reviewer','operator','viewer')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY,phone TEXT UNIQUE NOT NULL,first_name TEXT NOT NULL DEFAULT '',last_name TEXT NOT NULL DEFAULT '',timezone TEXT,timezone_source TEXT,custom_fields TEXT NOT NULL DEFAULT '{}',reply_hold INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS properties(id INTEGER PRIMARY KEY,contact_id INTEGER NOT NULL REFERENCES contacts(id),property_key TEXT UNIQUE NOT NULL,street_address TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT '',zip TEXT NOT NULL DEFAULT '',property_id TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consents(id INTEGER PRIMARY KEY,contact_id INTEGER NOT NULL REFERENCES contacts(id),business TEXT NOT NULL,channel TEXT NOT NULL,purpose TEXT NOT NULL,source TEXT NOT NULL,occurred_at TEXT NOT NULL,disclosure_version TEXT NOT NULL,evidence_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','verified','revoked')),verified_by TEXT,verified_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppressions(phone TEXT PRIMARY KEY,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppression_events(id INTEGER PRIMARY KEY,phone TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS templates(id INTEGER PRIMARY KEY,name TEXT NOT NULL,version INTEGER NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved')),approved_by TEXT,approved_at TEXT,created_at TEXT NOT NULL,UNIQUE(name,version));
CREATE TRIGGER IF NOT EXISTS immutable_template BEFORE UPDATE OF body,name,version ON templates BEGIN SELECT RAISE(ABORT,'Template content is immutable; create a new version'); END;
CREATE TABLE IF NOT EXISTS campaigns(id INTEGER PRIMARY KEY,name TEXT NOT NULL,template_id INTEGER NOT NULL REFERENCES templates(id),variant_ids TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'draft',mode TEXT NOT NULL DEFAULT 'simulation' CHECK(mode IN('simulation','production')),service_sid TEXT,sender TEXT,scheduled_at TEXT,approved_by TEXT,approved_at TEXT,pause_reason TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaign_contacts(campaign_id INTEGER NOT NULL REFERENCES campaigns(id),contact_id INTEGER NOT NULL REFERENCES contacts(id),property_id INTEGER REFERENCES properties(id),PRIMARY KEY(campaign_id,contact_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,campaign_id INTEGER NOT NULL REFERENCES campaigns(id),contact_id INTEGER NOT NULL REFERENCES contacts(id),property_id INTEGER REFERENCES properties(id),template_id INTEGER NOT NULL REFERENCES templates(id),kind TEXT NOT NULL DEFAULT 'automated' CHECK(kind IN('automated','manual')),mode TEXT NOT NULL CHECK(mode IN('simulation','production')),state TEXT NOT NULL DEFAULT 'queued',body TEXT NOT NULL,sender TEXT,service_sid TEXT,provider_sid TEXT UNIQUE,reason TEXT,scheduled_at TEXT NOT NULL,expires_at TEXT NOT NULL,claimed_at TEXT,accepted_at TEXT,segments INTEGER NOT NULL DEFAULT 1,estimated_cost REAL NOT NULL DEFAULT 0,actual_cost REAL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(campaign_id,contact_id,kind));
CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY,message_id INTEGER NOT NULL REFERENCES messages(id),state TEXT NOT NULL,provider_sid TEXT,error_code TEXT,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbound(id INTEGER PRIMARY KEY,provider_sid TEXT UNIQUE NOT NULL,contact_id INTEGER REFERENCES contacts(id),from_phone TEXT NOT NULL,to_phone TEXT NOT NULL,body TEXT NOT NULL,classification TEXT NOT NULL,owner TEXT,lead_status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events(id INTEGER PRIMARY KEY,event_key TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credentials(environment TEXT PRIMARY KEY CHECK(environment IN('simulation','production')),account_sid TEXT NOT NULL,api_key_sid TEXT NOT NULL,secret_encrypted TEXT NOT NULL,auth_token_encrypted TEXT NOT NULL,service_sid TEXT NOT NULL,verification TEXT NOT NULL DEFAULT '{}',verified_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_jobs(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,headers TEXT NOT NULL,rows TEXT NOT NULL,mapping TEXT NOT NULL,report TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'preview',created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_messages_queue ON messages(state,scheduled_at);
CREATE INDEX IF NOT EXISTS ix_messages_recipient ON messages(contact_id,accepted_at);
CREATE INDEX IF NOT EXISTS ix_consents_contact ON consents(contact_id,status);
CREATE INDEX IF NOT EXISTS ix_inbound_created ON inbound(created_at);
CREATE INDEX IF NOT EXISTS ix_audit_created ON audit_log(created_at);
